import math
distance = 0.0
def control(obs):
    global distance
    distance += max(0.0, -obs['motion']['v_mps']) * obs['dt']
    h = obs['hitch_deg']
    if distance >= 0.45 or h < -48:
        if abs(obs['motion']['v_mps']) < 0.02:
            wake('Turn set; inspect rear clearance')
        return (0, 0, 145)
    desired = -48.0
    feed = math.degrees(math.atan(1.25*math.sin(math.radians(desired))/(0.85+0.3*math.cos(math.radians(desired)))))
    steer = max(-45, min(45, feed + 3.5*(h-desired)))
    return (steer, -0.10, 145)

