import math
def fit(ps,x):
 n=len(ps)
 if n<2:return None
 sx=sum(p[0] for p in ps); sy=sum(p[1] for p in ps)
 ss=sum(p[0]*p[0] for p in ps); st=sum(p[0]*p[1] for p in ps)
 den=n*ss-sx*sx
 if abs(den)<0.01:return sy/n
 a=(n*st-sx*sy)/den
 return sy/n+a*(x-sx/n)
def control(obs):
 h=obs['hitch_deg']; cam=obs['views'].get('camera')
 if not cam:return (h*2, -0.5,-41)
 sides=[[],[]]
 for b,d in cam.get('walls',[]):
  a=math.radians(b+h); s=-d*math.cos(a); l=d*math.sin(a)
  if 0.5<s<14 and abs(l)>1.5:sides[l>0].append((s,l))
 c1=fit(sides[0],7); c2=fit(sides[1],7)
 if c1 is None or c2 is None:return (max(-35,min(35,2*h)), -0.6,-41)
 center=(c1+c2)/2
 goal=max(-32,min(32,math.degrees(math.atan(20.4*center/49))))
 steer=max(-40,min(40,1.8*(h-goal)+0.38*h))
 return (steer,-0.9,-41)

